    """
    Transition controller that only filters/guards transitions.
    It does not define, replace, or mutate any construction rule.
    """

    def __init__(
        self,
        target_rule_name: str = "supporting_safe_move",
        guard_bad_increase: int = 1,
        guard_require_ub_nonincreasing: bool = True,
        guard_require_sorted_destination: bool = True,
        guard_fallback_when_empty_safe_set: bool = True,
    ):
        self.target_rule_name = target_rule_name
        self.guard_bad_increase = guard_bad_increase
        self.guard_require_ub_nonincreasing = guard_require_ub_nonincreasing
        self.guard_require_sorted_destination = guard_require_sorted_destination
        self.guard_fallback_when_empty_safe_set = guard_fallback_when_empty_safe_set

    def initial(self, partial):
        return ()

    def _first_available_rule(self, rules):
        applies = getattr(rules, "applies", None)
        if callable(applies) and applies(self.target_rule_name):
            return self.target_rule_name
        return FALLBACK

    def select(self, partial, memory, rules):
        rule_name = self._first_available_rule(rules)
        if rule_name == FALLBACK:
